/* Swiss — strict grid, Inter Tight, black/white + one red accent, zero radius */
.theme-swiss {
  --bg: oklch(1 0 0);
  --surface: oklch(1 0 0);
  --surface-2: oklch(0.965 0 0);
  --fg: oklch(0.145 0 0);
  --fg-muted: oklch(0.5 0 0);
  --accent: oklch(0.55 0.235 27);
  --accent-fg: oklch(1 0 0);
  --accent-2: oklch(0.145 0 0);
  --line: oklch(0.145 0 0);
  --success: oklch(0.52 0.15 150);
  --warning: oklch(0.7 0.16 75);
  --danger: oklch(0.55 0.235 27);

  --radius: 0px;
  --radius-sm: 0px;
  --radius-lg: 0px;
  --radius-pill: 0px;

  --shadow-1: none;
  --shadow-2: none;
  --shadow-3: none;
  --glow: none;

  --border-width: 1px;
  --blur-amount: 0px;

  --font-display: "Inter Tight", "Helvetica Neue", Arial, sans-serif;
  --font-body: "Inter Tight", "Helvetica Neue", Arial, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.03em;
  --label-transform: uppercase;
  --label-tracking: 0.14em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-swiss h1,
.theme-swiss h2,
.theme-swiss h3 {
  letter-spacing: var(--tracking-display);
  font-weight: 600;
}

/* signature */
.theme-swiss { --font-ui: var(--font-display); }
.theme-swiss h1 { font-weight: 800; }
.theme-swiss button { text-transform: uppercase; letter-spacing: 0.08em; }
.theme-swiss ::selection { background: var(--accent); color: var(--accent-fg); }

/* depth */
.theme-swiss thead th { text-transform: uppercase; letter-spacing: var(--label-tracking); font-size: 0.72em; font-weight: 600; border-bottom: 2px solid var(--fg); text-align: left; }
.theme-swiss td { border-bottom: 1px solid oklch(0.145 0 0 / 15%); }
.theme-swiss tbody tr:hover { background: var(--surface-2); }
.theme-swiss input, .theme-swiss select, .theme-swiss textarea { border-radius: 0; border: 1px solid var(--fg); background: var(--surface); }
.theme-swiss input:focus, .theme-swiss select:focus, .theme-swiss textarea:focus { outline: 2px solid var(--accent); outline-offset: -2px; box-shadow: none; }
.theme-swiss a { text-decoration-thickness: 2px; text-underline-offset: 3px; }
.theme-swiss a:hover { color: var(--accent); }
.theme-swiss kbd { font-family: var(--font-mono); font-size: 0.85em; padding: 0.1em 0.45em; border: 1px solid var(--fg); border-radius: 0; background: var(--surface); }
.theme-swiss ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-swiss ::-webkit-scrollbar-track { background: var(--surface-2); }
.theme-swiss ::-webkit-scrollbar-thumb { background: var(--fg); border-radius: 0; }
.theme-swiss ::-webkit-scrollbar-thumb:hover { background: var(--accent); }
.theme-swiss .label-caps { font-weight: 600; border-top: 1px solid var(--fg); padding-top: 0.35em; }
.theme-swiss .themed-border { border-left: 4px solid var(--accent); }
/* physical: hard mechanical press, no easing — the grid does not bounce */
.theme-swiss button:active { transform: translate(1px, 1px); transition: none; }

/* alt mode: night grid — same strict rules, inverted plate, red survives */
.theme-swiss.alt-mode {
  --bg: oklch(0.145 0.000 0.0);
  --surface: oklch(0.185 0.000 0.0);
  --surface-2: oklch(0.225 0.000 0.0);
  --fg: oklch(0.97 0.005 90);
  --fg-muted: oklch(0.70 0.01 90);
  --line: oklch(0.97 0.005 90);
  --accent: oklch(0.62 0.24 27);
  --shadow-1: none;
  --shadow-2: none;
  --shadow-3: none;
}
.theme-swiss.alt-mode td { border-bottom-color: oklch(0.97 0.005 90 / 20%); }
.theme-swiss.alt-mode input, .theme-swiss.alt-mode select, .theme-swiss.alt-mode textarea { border-color: var(--fg); background: var(--surface); }
.theme-swiss.alt-mode kbd { border-color: var(--fg); background: var(--surface); }
.theme-swiss.alt-mode ::-webkit-scrollbar-thumb { background: var(--fg); }
.theme-swiss.alt-mode thead th, .theme-swiss.alt-mode .label-caps { border-color: var(--fg); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
